// thread_local: these are per-pair working tables rewritten on every
// rotatd/rotmat/spcore call (Fortran COMMON semantics), so they must be
// per-thread under the dcart OpenMP atom-pair loop.
// thread_local POD arrays (not std::vector): rewritten on every
// rotatd/rotmat/spcore pair call, so they must be per-thread under the dcart
// OpenMP atom-pair loop.  thread_local std::vector has lazy per-thread
// construction that breaks early (static-init) access, hence C arrays, which
// are allocated in TLS at compile time.
thread_local double cored[11][3] = {};
thread_local double sp[4][4] = {};
thread_local double sd[6][6] = {};
// F90 mndod_C.F90:20-22: pp(6,3,3), dp(15,5,3), d_d(15,5,5).
// C++ code indexes pp[i][k-1][j-1] with i=1..6 (1-based), so pad first
// dimension by one; second/third dims are 0-based (k-1/j-1).
// F90 mndod_C.F90:20-22 declares pp(6,3,3), dp(15,5,3), d_d(15,5,5) but
// rotmat FILLS and tx/elenuc READ them with 1-based direct subscripts
// (pp(i,k,l), k,l=1..3), including pp(1,3,l) for the 4th p-orbital.  So the
// C++ containers must have slots for subscripts 1..N plus a spare 0 slot:
// pp[i][1..3][1..3], dp[i][1..5][1..3], d_d[i][1..5][1..5].
thread_local double pp[7][4][4] = {};
thread_local double dp[16][6][4] = {};
thread_local double d_d[16][6][6] = {};
